from .frequency_units import FrequencyUnits
from .signal_analyzer_factory import SignalAnalyzerFactory


class SignalAnalyzerFacade(object):

    @staticmethod
    def setup_signal_analyzer(model, ip, **kwargs):
        """
        Configures new signal analyzer device.
        :param model: model name of configured device
        :type model: str
        :param ip: IP address of device to which connection will be established
        :type ip: str
        :param kwargs: additional device parameters, i.e. port=5023, unlock_timeout=150
        :return: configured signal analyzer device
        :rtype: SignalAnalyzer
        :raises UnsupportedSignalAnalyzer: when given device model is not supported
        :raises DeviceLocked: when device doesn't became unlocked by other user before reaching timeout
        """
        return SignalAnalyzerFactory.create(model, ip, **kwargs)

    @staticmethod
    def set_mode(device, mode, timeout=20):
        """
        Sets given operating mode on given device.
        :param device: device on which this operation will be performed
        :type device: SignalAnalyzer
        :param mode: name of mode which will be set, i.e. SA
        :type mode: str
        :param timeout: time to wait for individual steps of this operation to be finished; defaults to 20 seconds
        :type timeout: int
        :raises IncorrectOperation: when unsupported mode is provided
        :raises UnsupportedOperation: when this operation is not supported by given device
        """
        device.set_mode(mode=mode, timeout=timeout)

    @staticmethod
    def get_mode(device, timeout=10):
        """
        Gets current operating mode from given device.
        :param device: device on which this operation will be performed
        :type device: SignalAnalyzer
        :param timeout: time to wait for individual steps of this operation to be finished; defaults to 10 seconds
        :type timeout: int
        :return: device's current operating mode
        :rtype: str
        :raises UnsupportedOperation: when this operation is not supported by given device
        """
        return device.get_mode(timeout=timeout)

    @staticmethod
    def set_center_frequency(device, frequency, unit, timeout=10):
        """
        Sets given center frequency on given device.
        :param device: device on which this operation will be performed
        :type device: SignalAnalyzer
        :param frequency: value of frequency which will be set
        :type frequency: float
        :param unit: name of unit in which frequency is provided i.e. kHz
        :type unit: str
        :param timeout: time to wait for individual steps of this operation to be finished; defaults to 10 seconds
        :type timeout: int
        :raises IncorrectOperation: when device is not in appropriate mode, unsupported unit name is provided or
                                    frequency is out of allowed range
        :raises UnsupportedOperation: when this operation is not supported by given device
        """
        device.set_center_frequency(frequency=frequency, unit=unit, timeout=timeout)

    @staticmethod
    def get_center_frequency(device, unit=FrequencyUnits.Hz, timeout=10):
        """
        Gets current center frequency from given device.
        :param device: device on which this operation will be performed
        :type device: SignalAnalyzer
        :param unit: name of unit in which returned frequency should be expressed, i.e. kHz; defaults to Hz
        :type unit: str
        :param timeout: time to wait for individual steps of this operation to be finished; defaults to 10 seconds
        :type timeout: int
        :return: device's current center frequency
        :rtype: float
        :raises IncorrectOperation: when device is not in appropriate mode or unsupported unit name is provided
        :raises IncorrectResponse: when device responses with unhandled or incorrect message
        :raises UnsupportedOperation: when this operation is not supported by given device
        """
        return device.get_center_frequency(unit=unit, timeout=timeout)

