    @staticmethod
    def get_marker_y_axis(device, marker_id=1, timeout=10):
        """
        Gets Y axis value of given marker from given device.
        :param device: device on which this operation will be performed
        :type device: SignalAnalyzer
        :param marker_id: ID of marker for which Y axis value should be read; defaults to 1
        :type marker_id: int
        :param timeout: time to wait for individual steps of this operation to be finished; defaults to 10 seconds
        :type timeout: int
        :return: Y axis value of given marker
        :rtype: float
        :raises IncorrectOperation: when device is not in appropriate mode or marker ID is out of allowed range
        :raises IncorrectResponse: when device responses with unhandled or incorrect message
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        return device.get_marker_y_axis(marker_id=marker_id, timeout=timeout)
